// El backend ya decidio a quien escribirle y por que numero. Aqui solo se
// abre el arreglo en un item por sede y se deja traza: un solo lugar donde
// mirar cuando alguien pregunte "por que no me llego el recordatorio?".
const respuesta = $input.first().json;
const destinatarios = respuesta.destinatarios || [];

console.log(`[Recordatorio 21:00] Sedes sin movimientos hoy: ${destinatarios.length}`);

return destinatarios.map((d) => {
  // El backend ya normalizo el numero a digitos y validó el codigo de pais.
  // `via` dice como se resolvio (sede_telefono, sede_identidad o
  // usuario_telefono), y es lo primero que hay que mirar si alguien no recibe.
  console.log(
    `[Recordatorio 21:00] → ${d.negocio} / ${d.sede} [${d.via}]`,
  );

  return {
    json: {
      sedeId: d.sedeId,
      negocio: d.negocio,
      sede: d.sede,
      // Lo que ve el usuario. Se nombra la sede porque un mismo duenno puede
      // tener varias, cada una con su linea, y si no no sabria cual es cual.
      destino: `${d.negocio} (${d.sede})`,
      destinatario: d.destinatario,
      contacto: d.contacto,
      via: d.via,
    },
  };
});

// No se corta el workflow por un envío fallido: se registra y se sigue con
// los demás negocios.
for (const item of $input.all()) {
  const detalle = JSON.stringify(item.json).slice(0, 800);
  console.error('[Recordatorio 21:00] ERROR de envío:', detalle);
}
return $input.all();
